package com.example.petadoptioncommunity.adoption;
import com.example.petadoptioncommunity.identity.*;import com.example.petadoptioncommunity.web.*;import static com.example.petadoptioncommunity.web.Values.*;
import org.springframework.stereotype.Service;import java.util.*;
@Service public class AdoptionService {
 private final AdoptionMapper db;private final IdentityService identity;
 public AdoptionService(AdoptionMapper db,IdentityService identity){this.db=db;this.identity=identity;}
 public record Publish(String name,String category,String province,String region,String breed,String description,String image,String phone,String wechat,String email){}
 private Map<String,Object> publicPet(Map<String,Object> raw,IdentityPort.Actor actor){var p=row(raw);boolean owner=actor!=null&&p.get("publisherId").equals(actor.userId());boolean visible=actor!=null&&(owner||"AVAILABLE".equals(p.get("status"))||("HANDOVER".equals(p.get("status"))&&db.selected((String)p.get("id"),actor.userId())==1));if(!visible){p.remove("phone");p.remove("wechat");p.remove("email");}p.put("canContact",visible);p.put("isOwner",owner);return p;}
 public Object list(String keyword,String category,String region,String breed,int page){if(page<1||page>100000)throw bad("页码无效");String k=text(keyword,80,false),r=text(region,120,false),b=text(breed,80,false);var all=db.list().stream().map(p->publicPet(p,null)).filter(p->((String)p.get("name")).contains(k)&&(category==null||category.isBlank()||category.equals(p.get("category")))&&((p.get("province")+" "+p.get("region")).contains(r))&&((String)p.get("breed")).contains(b)).toList();return Map.of("items",all.stream().skip((long)(page-1)*12).limit(12).toList(),"total",all.size(),"page",page);}
 public Object detail(String id,IdentityPort.Actor a){uuid(id);return a==null?publicPet(db.pet(id),null):identity.withActiveActor(a,List.of(),()->publicPet(db.pet(id),a));}
 public Object publish(IdentityPort.Actor a,Publish v){String name=text(v.name,80,true),province=text(v.province,30,true),region=text(v.region,120,true),breed=text(v.breed,80,true),desc=text(v.description,1000,false),image=image(v.image),phone=text(v.phone,32,false),wechat=text(v.wechat,40,false),email=text(v.email,100,false);if(!Set.of("cat","dog").contains(v.category)||phone.isEmpty()&&wechat.isEmpty()&&email.isEmpty())throw bad("请选择猫狗类别并填写至少一种联系方式");return identity.withActiveActor(a,List.of(),()->{var p=new HashMap<String,Object>();p.putAll(Map.of("id",UUID.randomUUID().toString(),"publisherId",a.userId(),"name",name,"category",v.category,"province",province,"region",region,"breed",breed,"description",desc,"image",image));p.putAll(Map.of("phone",phone,"wechat",wechat,"email",email));db.insert(p);return publicPet(db.pet((String)p.get("id")),a);});}
 public Object apply(IdentityPort.Actor a,String petId){uuid(petId);return identity.withActiveActor(a,List.of(),()->{var p=row(db.lockPet(petId));if(a.userId().equals(p.get("publisherId")))throw bad("不能申请自己发布的宠物");if(!"AVAILABLE".equals(p.get("status")))throw conflict("该宠物当前不能申请");var existing=db.active(petId,a.userId());if(existing!=null)return row(existing);String id=UUID.randomUUID().toString();db.apply(id,petId,a.userId());return row(db.application(id));});}
 public Object dashboard(IdentityPort.Actor a){return identity.withActiveActor(a,List.of(),()->Map.of("pets",db.mine(a.userId()).stream().map(p->publicPet(p,a)).toList(),"applications",db.applications(a.userId()).stream().map(Values::row).toList()));}
 public Object act(IdentityPort.Actor a,String id,String action){uuid(id);if(!Set.of("select","success","failure").contains(action))throw bad("操作无效");return identity.withActiveActor(a,List.of(),()->{var initial=row(db.application(id));var p=row(db.lockPet((String)initial.get("petId")));var app=row(db.application(id));boolean owner=a.userId().equals(p.get("publisherId")),applicant=a.userId().equals(app.get("applicantId"));if(!owner&&!applicant)throw new ApiFailure(403,"FORBIDDEN","无权处理该申请");
 if(action.equals("select")){if(!owner)throw new ApiFailure(403,"FORBIDDEN","仅发布者可选定");if("HANDOVER".equals(p.get("status"))&&"SELECTED".equals(app.get("status")))return app;if(!"AVAILABLE".equals(p.get("status"))||!"PENDING".equals(app.get("status")))throw conflict("请刷新核对当前申请状态");db.applicationState(id,"SELECTED",false,false);db.petState((String)p.get("id"),"HANDOVER");}
 else {if("SUCCESS".equals(app.get("status"))&&action.equals("success"))return app;if("CANCELLED".equals(app.get("status"))&&action.equals("failure"))return app;if(!"HANDOVER".equals(p.get("status"))||!"SELECTED".equals(app.get("status")))throw conflict("此轮交接已结束或尚未开始");if(action.equals("failure")){db.applicationState(id,"CANCELLED",false,false);db.petState((String)p.get("id"),"AVAILABLE");}else{boolean pub=owner||bool(app,"publisherConfirmed"),ap=applicant||bool(app,"applicantConfirmed");db.applicationState(id,pub&&ap?"SUCCESS":"SELECTED",pub,ap);if(pub&&ap){db.petState((String)p.get("id"),"ADOPTED");db.closeOthers((String)p.get("id"));db.result((String)p.get("id"),id);}}}return row(db.application(id));});}
}
